ruby -Ilib:test -e '
require "application_system_test_case"

class LayoutCheckTest < ApplicationSystemTestCase
  include ActionView::RecordIdentifier

  test "inspect computed geometry" do
    card = cards(:logo)
    comment = comments(:logo_agreement_jz)
    sign_in_as(users(:david))
    visit card_url(card)

    within "##{dom_id(comment)}" do
      empty_info = page.evaluate_script(<<~JS)
        (() => {
          const r = document.querySelector("##{dom_id(comment)} .reactions")
          const t = r.querySelector(".reactions__trigger")
          const img = t.querySelector("img")
          return {
            reactions_pos: getComputedStyle(r).position,
            trigger_rect: t.getBoundingClientRect(),
            img_rect: img.getBoundingClientRect()
          }
        })()
      JS
      puts "EMPTY STATE: #{empty_info.inspect}"

      find(".reactions__trigger").click
      assert_selector "form.reaction__form"
      find(".reaction__menu-btn").click
      assert_selector "dialog.reaction__popup[open]"

      form_info = page.evaluate_script(<<~JS)
        (() => {
          const f = document.querySelector("##{dom_id(comment)} form.reaction__form")
          const av = f.querySelector(".reaction__avatar .avatar")
          const inp = f.querySelector(".reaction__input")
          const menuBtn = f.querySelector(".reaction__menu-btn")
          const subBtn = f.querySelector(".reaction__submit-btn")
          const canBtn = f.querySelector(".reaction__cancel-btn")
          const popup = f.querySelector("dialog.reaction__popup")
          return {
            form: f.getBoundingClientRect(),
            avatar: av.getBoundingClientRect(),
            input: inp.getBoundingClientRect(),
            menuBtn: menuBtn.getBoundingClientRect(),
            subBtn: subBtn.getBoundingClientRect(),
            canBtn: canBtn.getBoundingClientRect(),
            popup: popup.getBoundingClientRect()
          }
        })()
      JS
      puts "FORM STATE: #{form_info.inspect}"

      within "dialog.reaction__popup[open]" do
        click_button "Thumbs up"
      end
      find(".reaction__submit-btn").click
      assert_selector ".reaction.reaction--deleteable"

      find(".reaction.reaction--deleteable").click
      assert_selector ".reaction__delete", visible: true

      pill_info = page.evaluate_script(<<~JS)
        (() => {
          const p = document.querySelector("##{dom_id(comment)} .reaction")
          const av = p.querySelector(".reaction__avatar .avatar")
          const del = p.querySelector(".reaction__delete")
          return {
            pill: p.getBoundingClientRect(),
            avatar: av.getBoundingClientRect(),
            deleteBtn: del.getBoundingClientRect()
          }
        })()
      JS
      puts "PILL STATE: #{pill_info.inspect}"
    end
  end
end
' -- --name test_inspect_computed_geometry

